let accountRole='user',adminPersonalMode=false,adminTab='overview',adminQuery='',adminStatus='all',adminOffset=0,adminRenderId=0;
function addAdminEmailField(){const form=document.querySelector('#auth-form'),submit=document.querySelector('#auth-submit');if(!form||!submit)return;const box=document.createElement('div');box.id='admin-email-box';box.hidden=true;box.innerHTML='<label for="auth-admin-email">অ্যাডমিন ইমেইল</label><div class="auth-input"><span aria-hidden="true">@</span><input id="auth-admin-email" name="email" type="email" autocomplete="email" placeholder="অ্যাডমিনের ইমেইল লিখুন" disabled></div>';submit.before(box)}
function revealAdminEmail(){const box=document.querySelector('#admin-email-box'),input=document.querySelector('#auth-admin-email');if(!box||!input)return;box.hidden=false;input.disabled=false;input.required=true;input.focus()}
function adminLabel(value){return featureText(value)}
function adminNumber(value){return new Intl.NumberFormat(typeof uiLocale==='function'?uiLocale():'en-US').format(Number(value)||0)}
function adminDate(value){return value?new Intl.DateTimeFormat(uiLocale(),{dateStyle:'medium',timeStyle:'short'}).format(new Date(value)):adminLabel('আগের অ্যাকাউন্ট')}
function adminButtonIcon(name){return typeof profileIcon==='function'?profileIcon(name):''}
function renderAdmin(){if(accountRole!=='admin')return;const token=++adminRenderId;document.body.classList.add('is-admin');document.body.classList.remove('is-auth');window.DailyTallyTheme?.sync(db.settings?.theme||'system');document.querySelector('.developer-footer')?.setAttribute('hidden','');renderProfile();document.querySelector('#nav').innerHTML=[['overview','shield','সারসংক্ষেপ'],['users','phone','ব্যবহারকারী'],['settings','theme','সেটিংস']].map(([key,icon,label])=>'<button data-admin-tab="'+key+'" class="'+(adminTab===key?'active':'')+'" aria-current="'+(adminTab===key?'page':'false')+'">'+adminButtonIcon(icon)+'<span>'+label+'</span></button>').join('');document.querySelectorAll('[data-admin-tab]').forEach(button=>button.onclick=()=>{adminTab=button.dataset.adminTab;renderAdmin()});
 const intro='<section class="admin-hero"><span class="admin-eyebrow">অ্যাডমিন প্যানেল</span><h2>'+(adminTab==='users'?'ব্যবহারকারী ব্যবস্থাপনা':adminTab==='settings'?'আপনার অ্যাডমিন সেটিংস':'সবকিছু এক নজরে')+'</h2><p>DailyTally পরিচালনার জন্য আপনার নিজস্ব জায়গা।</p><span class="admin-verified">'+adminButtonIcon('shield')+'<span>অ্যাডমিন অ্যাক্সেস</span></span></section>';
 const search=adminTab==='users'?'<section class="admin-search-panel"><form id="admin-search-form"><label class="sr-only" for="admin-search">ব্যবহারকারী খুঁজুন</label><input id="admin-search" name="q" type="search" placeholder="নাম, নম্বর বা ইমেইল দিয়ে খুঁজুন" value="'+esc(adminQuery)+'"><select name="status" aria-label="অ্যাকাউন্টের অবস্থা">'+[['all','সব অ্যাকাউন্ট'],['active','চালু'],['blocked','বন্ধ']].map(([key,label])=>'<option value="'+key+'"'+(key===adminStatus?' selected':'')+'>'+label+'</option>').join('')+'</select><button class="primary">খুঁজুন</button></form></section>':'';
 document.querySelector('#app').innerHTML='<div class="admin-page">'+intro+search+'<div id="admin-body" aria-live="polite"><section class="admin-loading">লোড হচ্ছে…</section></div></div>';
 if(adminTab==='settings'){document.querySelector('#admin-body').innerHTML='<section class="admin-settings"><h2>অ্যাকাউন্ট ও পছন্দ</h2><div class="admin-account-copy"><strong data-user-text>'+esc(db.profile?.name||'DailyTally Admin')+'</strong><span data-user-text>'+esc(accountPhone)+'</span><span data-user-text>'+esc(accountEmail)+'</span></div>'+[['profile','edit','নাম ও ছবি পরিবর্তন করুন'],['password','shield','পাসওয়ার্ড পরিবর্তন'],['language','currency','ভাষা'],['theme','theme','থিম'],['personal','phone','আমার ব্যক্তিগত হিসাব']].map(([key,icon,label])=>'<button class="profile-setting-row" data-admin-setting="'+key+'"><span class="profile-row-icon">'+adminButtonIcon(icon)+'</span><span>'+label+'</span>'+adminButtonIcon('chevron')+'</button>').join('')+'<button class="admin-signout" id="admin-signout">লগআউট</button></section>';document.querySelectorAll('[data-admin-setting]').forEach(b=>b.onclick=()=>({profile:openProfile,password:showPasswordChange,language:openLanguageSettings,theme:openThemeSettings,personal:()=>{adminPersonalMode=true;tab='ড্যাশবোর্ড';render()}}[b.dataset.adminSetting])());document.querySelector('#admin-signout').onclick=()=>void logoutAccount();return}
 const form=document.querySelector('#admin-search-form');if(form)form.onsubmit=event=>{event.preventDefault();const values=new FormData(event.target);adminQuery=String(values.get('q')||'').trim();adminStatus=String(values.get('status')||'all');adminOffset=0;renderAdmin()};
 void loadAdminView(token);
}
async function loadAdminView(token){try{const result=await accountAPI(adminTab==='users'?'admin/users?q='+encodeURIComponent(adminQuery)+'&status='+adminStatus+'&offset='+adminOffset:'admin/overview');if(token!==adminRenderId||accountRole!=='admin'||adminPersonalMode)return;const root=document.querySelector('#admin-body');if(!root)return;
 if(adminTab==='overview'){root.innerHTML='<div class="admin-stats">'+[['phone','মোট ব্যবহারকারী',result.total],['shield','চালু অ্যাকাউন্ট',result.active],['trash','বন্ধ অ্যাকাউন্ট',result.blocked],['bell','চলমান লগইন',result.sessions]].map(([icon,label,value])=>'<section class="admin-stat"><span class="admin-stat-icon">'+adminButtonIcon(icon)+'</span><span>'+label+'</span><strong>'+adminNumber(value)+'</strong></section>').join('')+'</div><section class="admin-section"><div class="admin-section-title"><h2>ব্যবহারকারী পরিচালনা</h2><span class="admin-small-badge">'+adminNumber(result.admins)+' '+adminLabel('অ্যাডমিন')+'</span></div><p>অ্যাকাউন্ট খুঁজুন, চালু বা বন্ধ করুন এবং চলমান লগইন নিয়ন্ত্রণ করুন।</p><button class="primary" id="admin-open-users">ব্যবহারকারী দেখুন</button></section><section class="admin-section"><h2>সাম্প্রতিক অ্যাডমিন কার্যক্রম</h2>'+(result.actions.length?'<div class="admin-activity">'+result.actions.map(action=>'<div><span>'+adminLabel(action.action==='blocked'?'অ্যাকাউন্ট বন্ধ করা হয়েছে':action.action==='active'?'অ্যাকাউন্ট চালু করা হয়েছে':'চলমান লগইন বন্ধ করা হয়েছে')+'</span><small>'+esc(adminDate(action.created_at))+'</small></div>').join('')+'</div>':'<p class="muted">এখনও কোনো কার্যক্রম নেই।</p>')+'</section>';document.querySelector('#admin-open-users').onclick=()=>{adminTab='users';adminOffset=0;renderAdmin()};return}
 root.innerHTML='<section class="admin-user-section"><div class="admin-section-title"><h2>অ্যাকাউন্ট তালিকা</h2><span class="admin-small-badge">'+adminNumber(result.total)+'</span></div><div class="admin-user-list">'+(result.users.length?result.users.map(user=>'<button class="admin-user-card" data-admin-user="'+esc(user.id)+'"><span class="admin-user-avatar" data-user-text>'+esc((user.name||user.phone).slice(0,1).toUpperCase())+'</span><span class="admin-user-copy"><strong data-user-text>'+esc(user.name||user.phone)+'</strong><span data-user-text>'+esc(user.phone)+'</span><small data-user-text>'+esc(user.email||'—')+'</small></span><span class="admin-user-badges"><span class="admin-status '+(user.account_status==='blocked'?'blocked':'')+'">'+adminLabel(user.account_status==='blocked'?'বন্ধ':'চালু')+'</span>'+(user.role==='admin'?'<small>অ্যাডমিন</small>':'')+'</span></button>').join(''):'<p class="muted">কোনো অ্যাকাউন্ট পাওয়া যায়নি।</p>')+'</div><div class="admin-pagination"><button id="admin-prev" '+(result.offset===0?'disabled':'')+'>আগের পাতা</button><span>'+adminNumber(Math.floor(result.offset/result.limit)+1)+' / '+adminNumber(Math.max(1,Math.ceil(result.total/result.limit)))+'</span><button id="admin-next" '+(result.offset+result.limit>=result.total?'disabled':'')+'>পরের পাতা</button></div></section>';
 root.querySelectorAll('[data-admin-user]').forEach(button=>button.onclick=()=>openAdminUser(result.users.find(u=>u.id===button.dataset.adminUser)));document.querySelector('#admin-prev').onclick=()=>{adminOffset=Math.max(0,adminOffset-result.limit);renderAdmin()};document.querySelector('#admin-next').onclick=()=>{adminOffset+=result.limit;renderAdmin()};
 }catch(error){if(token!==adminRenderId||adminPersonalMode)return;const root=document.querySelector('#admin-body');if(root){root.innerHTML='<section class="admin-section"><p class="danger" role="alert">'+esc(featureText(error.message))+'</p><button id="admin-retry">আবার চেষ্টা করুন</button><button id="admin-exit">লগআউট</button></section>';document.querySelector('#admin-retry').onclick=renderAdmin;document.querySelector('#admin-exit').onclick=()=>void logoutAccount()}}}
function openAdminUser(user){if(!user)return;const d=featureDialog('অ্যাকাউন্টের তথ্য','<div class="admin-account-copy"><strong data-user-text>'+esc(user.name||user.phone)+'</strong><span data-user-text>'+esc(user.phone)+'</span><span data-user-text>'+esc(user.email||'—')+'</span></div><p>'+adminLabel('তৈরির সময়')+': '+esc(adminDate(user.created_at))+'</p>'+(user.role==='admin'?'<p>অ্যাডমিন অ্যাকাউন্ট সুরক্ষিত।</p>':'<div class="admin-user-actions"><button class="primary" data-admin-action="status">'+(user.account_status==='blocked'?'অ্যাকাউন্ট চালু করুন':'অ্যাকাউন্ট বন্ধ করুন')+'</button><button data-admin-action="revoke-sessions">সব লগইন বন্ধ করুন</button></div>')+'<p id="admin-action-error" class="danger" role="alert"></p>');d.querySelectorAll('[data-admin-action]').forEach(button=>button.onclick=async()=>{if(!confirm(button.dataset.adminAction==='status'?(user.account_status==='blocked'?'এই অ্যাকাউন্ট চালু করবেন?':'এই অ্যাকাউন্ট বন্ধ করলে user লগইন করতে পারবেন না। এগোবেন?'):'এই user-এর সব চলমান লগইন বন্ধ করবেন?'))return;d.querySelectorAll('[data-admin-action]').forEach(b=>b.disabled=true);try{await accountAPI('admin/users/'+button.dataset.adminAction,'POST',{id:user.id,status:user.account_status==='blocked'?'active':'blocked'});d.close();renderAdmin()}catch(e){d.querySelector('#admin-action-error').textContent=e.message;d.querySelectorAll('[data-admin-action]').forEach(b=>b.disabled=false)}})}
